def f(g, mode='uniform'):
    h,w=len(g),len(g[0])
    cnt=collections.Counter(v for r in g for v in r); fill=max(cnt,key=lambda k:cnt[k])
    sr=[i for i in range(h) if not any(g[i][j]==fill for j in range(w))]
    sc=[j for j in range(w) if not any(g[i][j]==fill for i in range(h))]
    out=[]
    for a in range(len(sr)-1):
        rr=[]
        for b in range(len(sc)-1):
            vals=set([g[sr[a]][sc[b]],g[sr[a]][sc[b+1]],g[sr[a+1]][sc[b]],g[sr[a+1]][sc[b+1]]])
            if len(vals)==1:
                v=next(iter(vals))
                val = v if v!=fill else fill
            elif len(vals)==2:
                v=vals-{fill}
                val = next(iter(v)) if len(v)==1 else fill
            else:
                val = fill
            # pure-line-corner: if corner value == line color, collapse to bg... but demos keep line color when uniform? demo2: corners(2,2,2,2)->bg; (9,9,9,9)? never uniform
            rr.append(val)
        out.append(rr)
    return out
