# parse separator lines: a line is a row/col that is entirely one color, except it may contain marker cells (color differs from bg). 
# Detect line color = the most frequent non-bg color whose full-row/full-col coverage is complete
def sep_lines(g):
    h,w=len(g),len(g[0])
    cnt=collections.Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    # candidate line colors: colors that appear in almost-full rows or cols
    res=[]
    for i in range(h):
        vals=g[i]; c=Counter(vals)
        top=c.most_common(1)[0][0]
        if len([v for v in vals if v==top])==w: res.append(('H',i,top))
    for j in range(w):
        vals=[g[i][j] for i in range(h)]; c=Counter(vals)
        top=c.most_common(1)[0][0]
        if len([v for v in vals if v==top])==h: res.append(('V',j,top))
    return res,bg,g
