        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
def solve(g,frac_r,frac_c):
    h,w=len(g),len(g[0])
    cnt=collections.Counter(v for r in g for v in r); bg=cnt.most_common(1)[0][0]
    lc=max([v for v,_ in cnt.most_common() if v!=bg],key=lambda v:cnt[v])
    sr=[i for i in range(h) if sum(x==lc for x in g[i])/w>=frac_r]
    sc=[j for j in range(w) if sum(g[i][j]==lc for i in range(h))/h>=frac_c]
    out=[]
    for a in range(len(sr)-1):
        row=[]
        for b_ in range(len(sc)-1):
            c=collections.Counter({g[sr[a]][sc[b_]],g[sr[a]][sc[b_+1]],g[sr[a+1]][sc[b_]],g[sr[a+1]][sc[b_+1]]})
            nonline={v:c[v] for v in c if v!=lc}
            if nonline:
                v=max(nonline,key=nonline.get); row.append(v)
            else: row.append(bg)
        out.append(row)
    return out,bg,lc,sr,sc
