import os,re,json,collections
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
def solve(g,frac=0.75):
    h,w=len(g),len(g[0])
    cnt=collections.Counter(v for r in g for v in r); bg=cnt.most_common(1)[0][0]
    lc=max([v for v,_ in cnt.most_common() if v!=bg],key=lambda v:cnt[v])
    sr=[i for i in range(h) if sum(x==lc for x in g[i])/w>=frac]
    sc=[j for j in range(w) if sum(g[i][j]==lc for i in range(h))/h>=frac]
    out=[]
    for a in range(len(sr)-1):
        row=[]
        for b_ in range(len(sc)-1):
            corners={g[sr[a]][sc[b_]],g[sr[a]][sc[b_+1]],g[sr[a+1]][sc[b_]],g[sr[a+1]][sc[b_+1]]}
            # ignore cells whose corner set doesn't include any valid candidate
            vals=set(corners)-{lc}
            uniq={v for v in vals if v!=bg}
            if len(uniq)==1:
                # ensure marker appears at all present corners (check against actual corner values excluding lc/bg)
                actual={v for v in corners if v!=lc and v!=bg}
                if actual<=uniq:
                    row.append(list(uniq)[0])
                else:
                    row.append(bg)
            else:
                row.append(bg)
        out.append(row)
    return out,bg,lc,sr,sc
for n in [1,2,3,4]:
    got,bg,lc,sr,sc=solve(G[f'Demo pair {n} input'])
    print(f'demo{n}: match={got==G[f"Demo pair {n} output"]}, H={sr} V={sc}')
ti=G['Test input']
got,bg,lc,sr,sc=solve(ti,0.75)
print(json.dumps(got))
